import base64
import hashlib
import struct
import sys
from pathlib import Path

OUT = Path('stage2.png')
CHECK = 'c54c797f8a71aa94'


def idat_of(data):
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        sys.exit("PNG ではありません")
    pos, idat = 8, b""
    while pos + 8 <= len(data):
        length, ctype = struct.unpack(">I4s", data[pos:pos + 8])
        if ctype == b"IDAT":
            idat += data[pos + 8:pos + 8 + length]
        if ctype == b"IEND":
            break
        pos += 12 + length
    return idat


def keystream(key, n):
    out = bytearray()
    counter = 0
    while len(out) < n:
        out += hashlib.sha256(key + struct.pack(">Q", counter)).digest()
        counter += 1
    return bytes(out[:n])


def main():
    if len(sys.argv) != 2:
        sys.exit(f"usage: python3 {Path(sys.argv[0]).name} <画像ファイル>")
    cargo = base64.b64decode(CARGO)
    key = hashlib.sha256(idat_of(Path(sys.argv[1]).read_bytes())).digest()
    ks = keystream(key, len(cargo))
    plain = (int.from_bytes(cargo, "big") ^ int.from_bytes(ks, "big")).to_bytes(len(cargo), "big")
    if hashlib.sha256(plain).hexdigest()[:16] != CHECK:
        sys.exit("鍵が合いません")
    OUT.write_bytes(plain)
    print('凍ったヘビを溶かすことはできた。しかし、赤い血が通ったのは、尻尾のいちばん先っぽだけだった。')


